query Customer($Query_customer_id: Int!, $Query_customer_customerItems_limit: Int!) {
  customer(id: $Query_customer_id) {
    __typename
    id
    name
    email
    customerItems(limit: $Query_customer_customerItems_limit) {
      __typename
      customerId
      id
      label
      quantity
    }
  }
}

fafa4635a5a671d82ac072ab5da9b8a38461125e:
query CustomerPage($Query_customerPage_first: Int, $Query_customerPage_after: String, $Query_customerPage_last: Int, $Query_customerPage_before: String, $Query_customerPage_pageItems_first: Int, $Query_customerPage_pageItems_after: String, $Query_customerPage_pageItems_last: Int, $Query_customerPage_pageItems_before: String) {
  customerPage(
    first: $Query_customerPage_first
    after: $Query_customerPage_after
    last: $Query_customerPage_last
    before: $Query_customerPage_before
  ) {
    __typename
    pageInfo {
      __typename
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    edges {
      __typename
      cursor
      node {
        __typename
        id
        name
        email
        pageItems(
          first: $Query_customerPage_pageItems_first
          after: $Query_customerPage_pageItems_after
          last: $Query_customerPage_pageItems_last
          before: $Query_customerPage_pageItems_before
        ) {
          __typename
          pageInfo {
            __typename
            hasNextPage
            hasPreviousPage
            startCursor
            endCursor
          }
          edges {
            __typename
            cursor
            node {
              __typename
              customerId
              id
              label
              quantity
            }
          }
        }
      }
    }
  }
}

8e1187e04bbbe345b32128537bc185c4a3ac01fb:
query Customers($Query_customers_limit: Int!, $Query_customers_items_limit: Int!) {
  customers(limit: $Query_customers_limit) {
    __typename
    id
    name
    email
    items(limit: $Query_customers_items_limit) {
      __typename
      customerId
      id
      label
      quantity
    }
  }
}
